create extension if not exists pgcrypto;
create type public.product_status as enum ('draft','active','archived');
create type public.order_status as enum ('pending','confirmed','processing','ready_for_dispatch','shipped','out_for_delivery','delivered','cancelled','returned');
create type public.payment_status as enum ('pending','processing','paid','failed','cancelled','refunded','partially_refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text,phone text,created_at timestamptz not null default now());
create table public.roles(id uuid primary key default gen_random_uuid(),name text unique not null);
create table public.permissions(id uuid primary key default gen_random_uuid(),key text unique not null);
create table public.role_permissions(role_id uuid references public.roles on delete cascade,permission_id uuid references public.permissions on delete cascade,primary key(role_id,permission_id));
create table public.user_roles(user_id uuid references auth.users on delete cascade,role_id uuid references public.roles on delete cascade,primary key(user_id,role_id));
create table public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,full_name text not null,phone text not null,alternate_phone text,address_line text not null,landmark text,city text not null,region text not null,ghana_post_gps text,delivery_notes text,is_default boolean not null default false,created_at timestamptz not null default now());
create table public.brands(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null,logo_path text,is_active boolean not null default true);
create table public.categories(id uuid primary key default gen_random_uuid(),parent_id uuid references public.categories, name text not null,slug text unique not null,description text,image_path text,sort_order int not null default 0,seo_title text,seo_description text,is_active boolean not null default true);
create table public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,short_description text,description text,sku text unique not null,brand_id uuid references public.brands,price_minor bigint not null check(price_minor>=0),compare_at_minor bigint check(compare_at_minor>=0),cost_minor bigint check(cost_minor>=0),currency char(3) not null default 'GHS',status public.product_status not null default 'draft',track_inventory boolean not null default true,allow_backorder boolean not null default false,weight_grams int,warranty text,seo_title text,seo_description text,is_featured boolean not null default false,is_best_seller boolean not null default false,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_categories(product_id uuid references public.products on delete cascade,category_id uuid references public.categories on delete cascade,primary key(product_id,category_id));
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,name text not null,sku text unique not null,options jsonb not null default '{}',price_minor bigint,weight_grams int,status public.product_status not null default 'active',created_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,variant_id uuid references public.product_variants on delete cascade,path text not null,alt_text text not null,sort_order int not null default 0);
create table public.inventory(id uuid primary key default gen_random_uuid(),product_id uuid references public.products on delete cascade,variant_id uuid references public.product_variants on delete cascade,quantity int not null default 0,low_stock_threshold int not null default 5,unique nulls not distinct(product_id,variant_id),check(product_id is not null));
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),inventory_id uuid not null references public.inventory,quantity_delta int not null,reason text not null,reference_type text,reference_id uuid,actor_id uuid references auth.users,created_at timestamptz not null default now());
create table public.carts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users on delete cascade,anonymous_token_hash text,expires_at timestamptz,created_at timestamptz not null default now());
create table public.cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references public.carts on delete cascade,product_id uuid not null references public.products,variant_id uuid references public.product_variants,quantity int not null check(quantity>0),unique nulls not distinct(cart_id,product_id,variant_id));
create table public.shipping_zones(id uuid primary key default gen_random_uuid(),name text not null,regions text[] not null,fee_minor bigint not null check(fee_minor>=0),free_shipping_threshold_minor bigint,estimate text not null,is_active boolean not null default true);
create table public.discount_codes(id uuid primary key default gen_random_uuid(),code text unique not null,kind text not null check(kind in('percentage','fixed')),value bigint not null check(value>0),minimum_minor bigint not null default 0,starts_at timestamptz,expires_at timestamptz,max_redemptions int,per_customer int,is_active boolean not null default true);
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,user_id uuid references auth.users,guest_email text,guest_phone text,status public.order_status not null default 'pending',payment_status public.payment_status not null default 'pending',currency char(3) not null default 'GHS',subtotal_minor bigint not null,discount_minor bigint not null default 0,shipping_minor bigint not null,tax_minor bigint not null default 0,total_minor bigint not null,shipping_address jsonb not null,billing_address jsonb,customer_note text,admin_note text,idempotency_key text unique not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,product_id uuid references public.products,variant_id uuid references public.product_variants,product_name text not null,sku text not null,options jsonb not null default '{}',quantity int not null check(quantity>0),unit_price_minor bigint not null,cost_minor bigint,discount_minor bigint not null default 0,total_minor bigint not null);
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders on delete cascade,status public.order_status not null,note text,actor_id uuid references auth.users,created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,provider text not null default 'paystack',reference text unique not null,status public.payment_status not null default 'pending',amount_minor bigint not null,currency char(3) not null default 'GHS',provider_response jsonb,verified_at timestamptz,created_at timestamptz not null default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(),provider_event_id text unique not null,event_type text not null,payload jsonb not null,processed_at timestamptz,error text,created_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products,user_id uuid not null references auth.users,rating int not null check(rating between 1 and 5),title text,content text not null,verified_purchase boolean not null default false,status text not null default 'pending',created_at timestamptz not null default now(),unique(product_id,user_id));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users,action text not null,entity_type text not null,entity_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index products_search_idx on public.products using gin(to_tsvector('english',name||' '||coalesce(description,'')||' '||sku));create index orders_user_idx on public.orders(user_id,created_at desc);create index inventory_variant_idx on public.inventory(variant_id);create index audit_logs_created_idx on public.audit_logs(created_at desc);
create or replace function public.has_permission(permission_key text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id join public.permissions p on p.id=rp.permission_id where ur.user_id=auth.uid() and p.key=permission_key)$$;
alter table public.profiles enable row level security;alter table public.addresses enable row level security;alter table public.products enable row level security;alter table public.product_variants enable row level security;alter table public.product_images enable row level security;alter table public.inventory enable row level security;alter table public.inventory_movements enable row level security;alter table public.carts enable row level security;alter table public.cart_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.order_status_history enable row level security;alter table public.payments enable row level security;alter table public.payment_events enable row level security;alter table public.reviews enable row level security;alter table public.audit_logs enable row level security;
create policy "public active products" on public.products for select using(status='active');create policy "public active variants" on public.product_variants for select using(status='active');create policy "profiles own" on public.profiles for select using(id=auth.uid());create policy "addresses own" on public.addresses for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "orders own" on public.orders for select using(user_id=auth.uid());create policy "order items own" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));create policy "reviews public approved" on public.reviews for select using(status='approved');create policy "reviews own insert" on public.reviews for insert with check(user_id=auth.uid());create policy "admin products" on public.products for all using(public.has_permission('products.manage')) with check(public.has_permission('products.manage'));create policy "admin inventory" on public.inventory for all using(public.has_permission('inventory.manage')) with check(public.has_permission('inventory.manage'));create policy "admin orders" on public.orders for all using(public.has_permission('orders.manage')) with check(public.has_permission('orders.manage'));create policy "admin audit" on public.audit_logs for select using(public.has_permission('audit.read'));
insert into public.roles(name) values('Super Admin'),('Admin'),('Sales'),('Inventory Manager'),('Fulfillment'),('Support');insert into public.permissions(key) values('products.manage'),('inventory.manage'),('orders.manage'),('customers.read'),('payments.read'),('reports.read'),('settings.manage'),('staff.manage'),('audit.read');
